mapper.select:
select pmr.id bindId,(select name from patient_base_info  where id = pmr.secondary_card_id )name,pmr.master_card_id masterCardId,pmr.secondary_card_id secondaryCardId,pmr.bind_type bindType
from patient_member_relation pmr join patient_base_info pbi on pmr.master_card_id = pbi.id
where pmr.master_card_id = #{form.patientId} and bind_type = #{form.bindType}

select id,patient_id masterCardId, member_type_id masterCardTypeId,
(select name from patient_base_info where id = patient_id) masterName,card_number masterCardNumber
from patient_member_info where patient_id = #{form.patientId}

select sum(amount) from (
    select IFNULL(sum(t.credit_amount),0) amount from member_recharge_toll_record t

        t.inservice = 1

            and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


            and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


            and t.org_id = #{query.orgId}


            and t.payment_id = #{query.payId}


    union all
    select IFNULL(sum(t.credit_amount),0) amount from prepaid_recharge_toll_record t

        t.inservice = 1

            and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


            and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


            and t.org_id = #{query.orgId}


            and t.payment_id = #{query.payId}


) as total

select sum(amount) from (
select IFNULL(sum(t.actual_return_amount),0) amount from member_return_record t

    t.inservice = 1

        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


        and t.org_id = #{query.orgId}


        and t.return_way_id = #{query.payId}


union all
select IFNULL(sum(t.actual_return_amount),0) amount from prepaid_return_record t

    t.inservice = 1

        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


        and t.org_id = #{query.orgId}


        and t.return_way_id = #{query.payId}


) as total
